\begin{remark}[A power-law example]
\label{rem:power-nonlinearity-semilinear-example}
\dcref{ch8:8.5.2-rem-1}
\group{Critical Point Theory}
The power-law PDE
\[
-\Delta u = |u|^{p-1}u
\]
satisfies the hypotheses (23)--(25).
\end{remark}

